import{_ as a,o as r,c as t,ag as i}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Scheduler Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/schedule/index.md","filePath":"proposals/schedule/index.md"}'),o={name:"proposals/schedule/index.md"};function s(n,e,d,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="scheduler-family-proposals" tabindex="-1">Scheduler Family proposals <a class="header-anchor" href="#scheduler-family-proposals" aria-label="Permalink to &quot;Scheduler Family proposals&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Historical / deferred candidate family</p><p><code>schedule.forms.takoform.com</code> is retained source from the earlier Provider projection. It is not part of the current official corpus (the single Edge family with 16 Forms), and this family is outside Current navigation. These pages are English-only historical/deferred proposals.</p></div><p>The Scheduler Family, <code>schedule.forms.takoform.com</code>, is minted under <a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>: the standalone scheduler is popularly offered as a managed service by every major provider and has no de-facto standard API, so a host-neutral contract is the only portability there is. Its member fixes, completely, the application-visible semantics of the proven standalone-cron shape — a cron expression firing one declared target under a declared retry policy — without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: firing semantics, grammar, delivery guarantees, update and delete units, and error semantics. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>This prose accompanies the generated Experimental <code>Schedule</code> candidate under <code>forms/candidates/schedule.forms.takoform.com</code>. The generated candidate bytes are retained historical/deferred source, not the current publisher identity; these documents reserve nothing.</p><h2 id="retained-candidate-member-historical-deferred" tabindex="-1">Retained candidate member (historical/deferred) <a class="header-anchor" href="#retained-candidate-member-historical-deferred" aria-label="Permalink to &quot;Retained candidate member (historical/deferred)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./schedule.html">Schedule</a></td><td>identity</td><td>Five-field UTC cron firing one declared message at one pinned cross-family target, at-least-once, with declared retries and no catch-up replay.</td><td>Timezone-aware scheduling, HTTPS invocation, or backfill replay is a different Form.</td></tr></tbody></table><h2 id="contrast-with-the-edge-cron-trigger" tabindex="-1">Contrast with the edge cron trigger <a class="header-anchor" href="#contrast-with-the-edge-cron-trigger" aria-label="Permalink to &quot;Contrast with the edge cron trigger&quot;">​</a></h2><p>The Edge Platform Family&#39;s <a href="./../edge/worker-cron-trigger.html">WorkerCronTrigger</a> is an attachment: it activates a worker the family already has, and the worker&#39;s code is the payload. A Schedule is an identity that owns its own existence and its own declared payload — it needs no worker, and its target is an exact cross-family reference (in MVP, a <code>PullQueue</code> send or a <code>Topic</code> publish). The two deliberately share one cron grammar so an expression valid in one is valid in the other. Designs that differ — <code>TimezoneSchedule</code>, an HTTPS invocation target — are separate Form work per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',10)])])}const f=a(o,[["render",s]]);export{m as __pageData,f as default};
